mkdir -p src test && cat > package.json <<'EOF'
{
  "name": "set-proto",
  "version": "0.1.0",
  "description": "Cross-platform helper to set the prototype of an object at runtime",
  "main": "src/index.js",
  "types": "src/index.d.ts",
  "files": [
    "src"
  ],
  "scripts": {
    "test": "node --test"
  },
  "keywords": [
    "prototype",
    "setPrototypeOf",
    "__proto__"
  ],
  "license": "MIT",
  "engines": {
    "node": ">=18"
  }
}
EOF
cat > src/index.js <<'EOF'
'use strict';

/**
 * Set the prototype of `obj` to `proto` and return `obj`.
 *
 * Uses the native Object.setPrototypeOf where available (all ES2015+ engines),
 * falls back to the __proto__ setter, and finally to copying properties for
 * legacy engines that support neither.
 */
var setPrototypeOf =
  Object.setPrototypeOf ||
  ({ __proto__: [] } instanceof Array ? setProtoOf : mixinProperties);

function setProtoOf(obj, proto) {
  obj.__proto__ = proto;
  return obj;
}

function mixinProperties(obj, proto) {
  for (var prop in proto) {
    if (!Object.prototype.hasOwnProperty.call(obj, prop)) {
      obj[prop] = proto[prop];
    }
  }
  return obj;
}

module.exports = setPrototypeOf;
module.exports.setProtoOf = setProtoOf;
module.exports.mixinProperties = mixinProperties;
EOF
cat > src/index.d.ts <<'EOF'
declare function setPrototypeOf<T extends object>(obj: T, proto: object | null): T;

declare namespace setPrototypeOf {
  function setProtoOf<T extends object>(obj: T, proto: object | null): T;
  function mixinProperties<T extends object>(obj: T, proto: object): T;
}

export = setPrototypeOf;
EOF
cat > test/index.test.js <<'EOF'
'use strict';

const test = require('node:test');
const assert = require('node:assert');
const setPrototypeOf = require('..');
const { setProtoOf, mixinProperties } = setPrototypeOf;

test('uses native Object.setPrototypeOf when available', () => {
  assert.strictEqual(setPrototypeOf, Object.setPrototypeOf);
});

test('sets the prototype and returns the object', () => {
  const proto = { greet() { return 'hi'; } };
  const obj = {};
  assert.strictEqual(setPrototypeOf(obj, proto), obj);
  assert.strictEqual(Object.getPrototypeOf(obj), proto);
  assert.strictEqual(obj.greet(), 'hi');
});

test('supports a null prototype', () => {
  const obj = setPrototypeOf({}, null);
  assert.strictEqual(Object.getPrototypeOf(obj), null);
});

test('__proto__ fallback sets the prototype', () => {
  const proto = { a: 1 };
  const obj = setProtoOf({}, proto);
  assert.strictEqual(Object.getPrototypeOf(obj), proto);
});

test('mixin fallback copies properties without overwriting own ones', () => {
  const obj = mixinProperties({ a: 'own' }, { a: 'proto', b: 2 });
  assert.deepStrictEqual(obj, { a: 'own', b: 2 });
});
EOF
cat > .gitignore <<'EOF'
node_modules/
*.log
coverage/
EOF
cat > README.md <<'EOF'
# set-proto

Cross-platform way to set the prototype of an object at runtime.

```js
const setPrototypeOf = require('set-proto');

const obj = setPrototypeOf({}, { greet() { return 'hi'; } });
obj.greet(); // 'hi'
```

Uses the native `Object.setPrototypeOf` when available, falling back to the
`__proto__` setter and finally to copying properties on legacy engines.

## Development

```sh
npm test
```
EOF
npm test 2>&1 | tail -12

